// План specs/dashboard.md 4.1 (#0cd6c0). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// Приветствие на Home «N clients · M estimates»: M = Total Estimates на /assessments (учитываются все сметы, в т.ч. Draft),
// и при каждой загрузке (перезагрузка + переход внутри приложения) значение сразу верное — «0 estimates» не мелькает
// (решение пользователя 12.11: мелькание неверного значения — реджект; факты 17.11: 9/9 загрузок без мелькания).
// Не сверено с сайтом при записи: подпись «Total Estimates» и порядок значения рядом с ней.
import { test, expect } from '../../fixtures';
import { ROLE, pp } from '../pricebook/pricebook-helpers';
import { greetingCard } from './dashboard-helpers';

async function totalEstimates(page: import('@playwright/test').Page): Promise<number> {
  await page.goto(pp('/assessments'));
  await expect(page.getByText('Total Estimates', { exact: true })).toBeVisible({ timeout: 30_000 });
  let n = -1;
  await expect.poll(async () => {
    const text = await page.locator('main').innerText();
    const m = text.match(/Total Estimates\s*(\d+)/);
    n = m ? Number(m[1]) : -1;
    return n;
  }, { message: 'Total Estimates — число' }).toBeGreaterThanOrEqual(1);
  return n;
}

/** Записывает каждое значение «N estimates» в приветствии с момента загрузки страницы. */
async function watchGreetingEstimates(page: import('@playwright/test').Page) {
  await page.addInitScript(() => {
    const seen: string[] = [];
    (window as unknown as { __qaSeen: string[] }).__qaSeen = seen;
    const scan = () => {
      const el = document.querySelector('section.tec-persona');
      const m = el?.textContent?.match(/(\d+)\s+estimates?/i);
      if (m && seen[seen.length - 1] !== m[1]) seen.push(m[1]);
    };
    new MutationObserver(scan).observe(document, { childList: true, subtree: true, characterData: true });
  });
}

test.describe('Dashboard — greeting estimates count (#0cd6c0)', () => {
  test('Greeting "N estimates" equals Total Estimates on /assessments and never flashes 0 across 3 reloads + SPA navigation #0cd6c0 @prod-safe', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
    await watchGreetingEstimates(page);

    const total = await totalEstimates(page);

    for (let i = 0; i < 3; i++) {
      await page.goto(pp('/dashboard'));
      await expect(greetingCard(page)).toContainText(new RegExp(`\\b${total} estimates?\\b`), { timeout: 30_000 });
      const seen = await page.evaluate(() => (window as unknown as { __qaSeen: string[] }).__qaSeen);
      expect(seen, `загрузка ${i + 1}: в приветствии с первого показа только ${total}, без «0»`).toEqual([String(total)]);
    }

    // SPA: Estimates → Home через меню (без перезагрузки страницы)
    await page.getByRole('link', { name: 'Estimates', exact: true }).filter({ visible: true }).first().click();
    await expect(page.getByText('Total Estimates', { exact: true })).toBeVisible();
    await page.getByRole('link', { name: 'Home', exact: true }).filter({ visible: true }).first().click();
    await expect(greetingCard(page)).toContainText(new RegExp(`\\b${total} estimates?\\b`), { timeout: 30_000 });
  });
});
